#!/usr/bin/env python3
"""Verify provenance and assemble unchanged Rust slices. This is NOT a parser port."""
import argparse, hashlib, json, pathlib
BASE = pathlib.Path(__file__).resolve().parent
SOURCE = 'crates/codegen/xai-grok-update/src/community_release.rs'
RANGES = [(31,35),(41,75),(98,107),(124,193),(232,250),(306,338),(344,441),(633,1018)]
HEADER = '''// Generated by verify_sources.py. No parser implementation is handwritten here.
// Historical commit: 3f5d07f8cb2e9be395131296a3efc4635713db7f
use std::collections::{HashMap, HashSet};
use std::fs::{File, OpenOptions};
use std::io::{Read, Write};
use std::path::Path;
use anyhow::{Context, Result};
use semver::Version;
use serde::Deserialize;
use sha2::{Digest, Sha256};
#[path = "../historical/crates/codegen/xai-grok-product/src/lib.rs"]
mod xai_grok_product;
#[path = "../historical/crates/codegen/xai-grok-update/src/community_release/package_protocol.rs"]
mod package_protocol;
use package_protocol::{BUILD_INFO, PackageProtocol};
'''
def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--check',action='store_true'); args=ap.parse_args()
    provenance=json.loads((BASE/'source-provenance.json').read_text(encoding='utf-8'))
    report={'commit':provenance['commit'],'source_checks':[],'extraction_ranges':RANGES}
    for f in provenance['files']:
        b=(BASE/'historical'/f['path']).read_bytes()
        actual=hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
        if actual != f['git_blob_sha1']: raise SystemExit(f"Git blob mismatch: {f['path']}")
        report['source_checks'].append({'path':f['path'],'git_blob_sha1':actual,'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b),'result':'PASS'})
    bridge=json.loads((BASE/'bridge-source-v1.0.8/provenance.json').read_text(encoding='utf-8'))
    b=(BASE/'bridge-source-v1.0.8/community_release.rs').read_bytes()
    bridge_blob=hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
    assert bridge_blob==bridge['source']['git_blob_sha1'], 'v1.0.8 source blob changed'
    report['bridge_source_check']={'commit':bridge['tag']['object']['sha'],'git_blob_sha1':bridge_blob,'result':'PASS (source inspection only; not compiled)'}
    tag=json.loads((BASE/'historical-release-v1.0.45-tag.json').read_text(encoding='utf-8'))
    assert tag['tag']=='release-v1.0.45' and tag['object']['sha']==provenance['commit']
    lines=(BASE/'historical'/SOURCE).read_bytes().splitlines(keepends=True)
    generated=HEADER.encode()
    for start,end in RANGES:
        generated+=f'\n// Verbatim {SOURCE}:L{start}-L{end}\n'.encode()+b''.join(lines[start-1:end])
    generated+=b'\n#[cfg(test)]\n#[path = "compatibility_tests.rs"]\nmod compatibility_tests;\n'
    target=BASE/'src/historical.rs'
    if args.check:
        if target.read_bytes()!=generated: raise SystemExit('Generated Rust module differs from the verified historical slices')
    else: target.write_bytes(generated)
    report['generated_module_sha256']=hashlib.sha256(generated).hexdigest()
    report['rust_execution']='NOT EXECUTED by this provenance checker'
    (BASE/'results').mkdir(exist_ok=True)
    (BASE/'results/source-provenance-check.json').write_text(json.dumps(report,indent=2)+'\n')
    print(f"PASS: {len(report['source_checks'])} exact Git blobs and {len(RANGES)} unchanged Rust ranges verified")
if __name__=='__main__': main()
